/* rute penerbangan: enam titik, pesawat terbang menyusuri jalur (digerakkan JS, berhenti saat beranda tidak tampil) */
.rute2 { position: relative; padding: 6px 2px 2px; }
.rute2 > svg { position: absolute; left: 0; top: 0; width: 100%; height: 100%; overflow: visible; pointer-events: none; }
.rute2 .rute-langit { z-index: 0; }
.rute2 .rute-depan { z-index: 2; filter: drop-shadow(2px 6px 4px rgba(20, 19, 43, .35)); }
.rute-jalur { fill: none; stroke: var(--hair); stroke-width: 2.5; stroke-dasharray: 1 9; stroke-linecap: round; }
.rute-asap { fill: none; stroke: var(--accent-soft); stroke-width: 12; stroke-linecap: round; }
.rute-jejak { fill: none; stroke: var(--accent); stroke-width: 3; stroke-linecap: round; }
.rute-pesawat { opacity: 0; }
.rute-pesawat .pw-badan { fill: #ffffff; stroke: #14132b; stroke-width: 1.1; }
.rute-pesawat .pw-sayap, .rute-pesawat .pw-ekor { fill: var(--accent); stroke: #14132b; stroke-width: 1; stroke-linejoin: round; }
.rute-pesawat .pw-kaca { fill: #8fd3ff; }
.rute2 ol { position: relative; z-index: 1; list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 10px; }
.rute2 li { display: flex; flex-direction: column; align-items: center; text-align: center; gap: 2px; }
.rute2 .titik { width: 46px; height: 46px; flex: 0 0 auto; border-radius: 50%; display: grid; place-items: center; border: 2px solid var(--ink); background: var(--surface); color: var(--ink); font-family: var(--f-mono); font-weight: 700; font-size: 14px; margin-bottom: 44px; transition: background-color .45s ease, color .45s ease, transform .35s ease, box-shadow .35s ease; }
.rute2 li:nth-child(even) .titik { margin: 44px 0 0; }
.rute2 li:nth-child(even) small { margin-top: 8px; }
.rute2 li.lewat .titik { background: var(--pop); color: #14132b; }
.rute2 li.singgah .titik { transform: scale(1.16); box-shadow: 0 0 0 6px var(--accent-soft), 0 0 22px var(--accent); }
.rute2 small { font-family: var(--f-mono); font-size: 10.5px; font-weight: 600; letter-spacing: .08em; text-transform: uppercase; color: var(--accent); }
.rute2 li b { font-family: var(--f-display); font-size: 16px; font-weight: 800; line-height: 1.25; }
.rute2 .ket { color: var(--muted); font-size: 13.5px; line-height: 1.4; }
@media (max-width: 760px) {
  .rute2 ol { grid-template-columns: minmax(0, 1fr); gap: 0; }
  .rute2 li { display: grid; grid-template-columns: 46px minmax(0, 1fr); column-gap: 16px; align-items: start; text-align: left; padding-bottom: 18px; }
  .rute2 li:last-child { padding-bottom: 0; }
  .rute2 li .titik, .rute2 li:nth-child(even) .titik { grid-row: 1 / span 3; margin: 0; }
  .rute2 li:nth-child(even) small { margin-top: 0; }
  .rute2 li small, .rute2 li b, .rute2 li .ket { grid-column: 2; }
}

/* tutorial pasang aplikasi di beranda */
.pasang { scroll-margin-top: 16px; }
.pasang.sorot { animation: sorotPasang 1.6s ease; }
@keyframes sorotPasang { 0%, 60% { box-shadow: 0 0 0 5px var(--accent-soft), 5px 5px 0 var(--shadow); border-color: var(--accent); } 100% { box-shadow: 5px 5px 0 var(--shadow); } }
.pasang-kepala { display: flex !important; flex-direction: row !important; align-items: center; gap: 16px !important; }
.pasang-kepala .pasang-ikon { width: 64px; height: 64px; flex: 0 0 auto; border-radius: 16px; box-shadow: 0 6px 18px rgba(20, 19, 43, .25); }
.pasang-kepala h2 { font-size: 26px; font-weight: 800; }
.pasang-kepala p { color: var(--muted); font-size: 15px; max-width: 60ch; }
.pasang-aksi { display: flex; flex-wrap: wrap; align-items: center; gap: 10px 16px; }
.pasang-aksi .tombol svg { vertical-align: -3px; margin-right: 2px; }
.pasang-status { margin: 0; font-size: 14.5px; color: var(--ink); flex: 1 1 260px; }
.pasang.terpasang .pasang-status { color: var(--ok); }
.pasang-pilih { display: inline-flex; align-self: flex-start; border: 2px solid var(--ink); border-radius: 999px; padding: 3px; gap: 3px; background: var(--sunk); }
.pasang-pilih button { border: 0; background: transparent; padding: 7px 16px; border-radius: 999px; font-weight: 700; font-size: 14.5px; cursor: pointer; color: var(--muted); }
.pasang-pilih button[aria-selected="true"] { background: var(--accent); color: var(--accent-ink); }
.pasang-langkah { list-style: none; margin: 0; padding: 0; display: grid; grid-template-columns: repeat(auto-fit, minmax(190px, 1fr)); gap: 12px; }
.pasang-langkah li { display: flex; gap: 12px; align-items: flex-start; padding: 14px; border: 2px solid var(--hair); border-radius: var(--r-sm); background: var(--sunk); font-size: 14.5px; line-height: 1.5; }
.pasang-langkah li i { font-style: normal; flex: 0 0 auto; width: 28px; height: 28px; border-radius: 50%; display: grid; place-items: center; background: var(--pop); color: #14132b; font-family: var(--f-mono); font-weight: 700; font-size: 13.5px; border: 2px solid var(--ink); }
.pasang-langkah .ikon-ui { vertical-align: -3px; }
.pasang-catatan { margin: 0; font-size: 13.5px; color: var(--muted); }
@media (max-width: 520px) {
  .pasang-kepala .pasang-ikon { width: 54px; height: 54px; border-radius: 13px; }
  .pasang-kepala h2 { font-size: 22px; }
  .pasang-aksi .tombol { width: 100%; justify-content: center; }
}

