@keyframes maJatuh { 0%, 70% { opacity: 0; transform: translate(40px, 10px); stroke-dashoffset: 0; } 72% { opacity: .9; } 84% { opacity: 0; transform: translate(150px, 50px); stroke-dashoffset: -60; } 100% { opacity: 0; } }
@media (max-width: 680px) { .angkasa { grid-template-columns: minmax(0, 1fr); } .antariksa.mini { width: min(100%, 330px); margin: -10px auto -6px; } }
@media (prefers-reduced-motion: reduce) { .antariksa.mini * { animation: none !important; } }

/* ---------- beranda: ilustrasi antariksa realistis (gambar contoh prodi) + lapisan gerak ---------- */
.angkasa { grid-template-columns: minmax(0, 1fr) minmax(0, 1.04fr); }
.antariksa.foto { position: relative; width: calc(100% + 34px); margin: -18px -26px -18px -8px; aspect-ratio: 920 / 670; animation: ayun 9s ease-in-out infinite; }
.antariksa.foto > * { position: absolute; }
.antariksa.foto .af-dasar { inset: 0; width: 100%; height: 100%; max-width: none; }
.antariksa.foto .af-hidup { inset: 0; width: 100%; height: 100%; overflow: visible; pointer-events: none; }
.antariksa.foto .af-roket { height: auto; max-width: none; transform-origin: 30% 80%; animation: afRoket 3.2s ease-in-out infinite; filter: drop-shadow(0 0 10px rgba(255, 200, 90, .25)); }
@keyframes afRoket { 0%, 100% { transform: translate(0, 0) rotate(0deg); } 50% { transform: translate(5px, -4.5px) rotate(-1.5deg); } }
.antariksa.foto .af-awan { animation: afAwan 46s linear infinite; }
@keyframes afAwan { to { transform: translateX(-460px); } }
.antariksa.foto .af-lampu circle { fill: #ffe7a0; filter: drop-shadow(0 0 3px #ffc94a); transform-box: fill-box; transform-origin: center; animation: afLampu 2.6s ease-in-out infinite; }
@keyframes afLampu { 0%, 100% { opacity: .15; transform: scale(.6); } 50% { opacity: 1; transform: scale(1.2); } }
.antariksa.foto .af-simpul circle { transform-box: fill-box; transform-origin: center; mix-blend-mode: screen; animation: afSimpul 2.4s ease-in-out infinite; }
@keyframes afSimpul { 0%, 100% { opacity: .35; transform: scale(.7); } 50% { opacity: 1; transform: scale(1.25); } }
.antariksa.foto .af-bintang path { fill: #fff3c4; transform-box: fill-box; transform-origin: center; animation: afBintang 3s ease-in-out infinite; }
@keyframes afBintang { 0%, 100% { opacity: .9; transform: scale(1) rotate(0); } 50% { opacity: .2; transform: scale(.45) rotate(45deg); } }
.antariksa.foto .af-kilau { inset: 0; pointer-events: none; mix-blend-mode: screen; opacity: .9;
  background: linear-gradient(112deg, transparent 0 42%, rgba(255, 236, 180, .0) 44%, rgba(255, 240, 200, .55) 50%, rgba(255, 236, 180, 0) 56%, transparent 58% 100%) no-repeat; background-size: 260% 100%; animation: afKilau 6.5s ease-in-out infinite; }
@keyframes afKilau { 0%, 35% { background-position: 120% 0; } 70%, 100% { background-position: -30% 0; } }
@media (max-width: 680px) {
  .angkasa { grid-template-columns: minmax(0, 1fr); }
  .antariksa.foto { order: -1; width: calc(100% + 40px); margin: -16px -20px -8px; }
}

.langit .bulan.tetap { width: 70px; margin: 22px 22px 0 0; filter: drop-shadow(0 0 14px rgba(159, 140, 255, .45)); }
@media (max-width: 680px) { .langit .bulan.tetap { width: 52px; margin: 14px 18px 0 0; } }

/* ---------- beranda berlapis: globe WebGL berputar, cincin emas, patung, pesawat mengorbit (v54) ---------- */
.antariksa.foto .af-lapis { inset: 0; width: 100%; height: 100%; overflow: visible; pointer-events: none; }
.antariksa.foto .af-bumi { display: block; opacity: 0; transition: opacity .6s ease; }
.antariksa.foto.af-siap .af-bumi { opacity: 1; }
.antariksa.foto .af-dewi { height: auto; max-width: none; pointer-events: none; }
.af-cincin path { fill: none; stroke-linecap: round; }
.af-cincin .pendar { stroke: #ffae3c; stroke-width: 12; opacity: .45; }
.af-belakang .af-cincin .pendar { filter: url(#afPendar); } .af-depan .af-cincin .pendar { filter: url(#afPendar2); }
.af-cincin .tengah { stroke: #ffc957; stroke-width: 3.4; opacity: .95; }
.af-cincin .inti { stroke: #fff6da; stroke-width: 1.4; }
.af-cincin.c2 .pendar { stroke-width: 9; opacity: .34; } .af-cincin.c2 .tengah { stroke-width: 2.3; }
.af-cincin.c3 .pendar { stroke-width: 7; opacity: .22; } .af-cincin.c3 .tengah { stroke-width: 1.6; opacity: .75; } .af-cincin.c3 .inti { opacity: .7; }
.af-belakang .af-cincin { opacity: .78; }
.antariksa.foto .af-roket svg { position: absolute; inset: 0; width: 100%; height: 100%; overflow: visible; }
.antariksa.foto .af-roket img { position: absolute; height: auto; max-width: none; }
.af-roket .jejak { fill: none; stroke: url(#afJejak); stroke-width: 7; stroke-linecap: round; }
.af-roket .jejak-p { fill: none; stroke: url(#afJejak); stroke-width: 20; stroke-linecap: round; opacity: .55; }
.antariksa.foto .af-roket { filter: none; }
.antariksa.foto .af-roket img { filter: drop-shadow(0 0 10px rgba(255, 200, 90, .25)); }
/* cadangan bila WebGL tidak tersedia: gambar utuh v53 */
.antariksa.foto.af-statis .af-lapis, .antariksa.foto.af-statis .af-bumi, .antariksa.foto.af-statis .af-dewi, .antariksa.foto.af-statis .af-roket svg { display: none; }
.antariksa.foto .af-bola { height: auto; max-width: none; pointer-events: none; }
.antariksa.foto.af-statis .af-bola { display: none; }

/* ---------- v55: Dewi Keadilan mengintip dari balik globe sambil memperlihatkan timbangan; pesawat & jejak asap ---------- */
.antariksa.foto .af-dewi { pointer-events: none; transform-origin: 30% 86%; will-change: transform; filter: drop-shadow(0 0 14px rgba(255, 190, 80, .3));
  transform: translate(-12.7%, 1.33%) rotate(-2.5deg); animation: afIntip 12s infinite; }
@keyframes afIntip {
  0% { transform: translate(-12.7%, 1.33%) rotate(-2.5deg); }
  16% { transform: translate(-12.7%, 1.33%) rotate(-2.5deg); animation-timing-function: cubic-bezier(.55, 0, .22, 1); }
  37% { transform: translate(13.4%, -1.4%) rotate(1.6deg); }
  63% { transform: translate(13.4%, -1.4%) rotate(1.6deg); animation-timing-function: cubic-bezier(.6, 0, .3, 1); }
  85% { transform: translate(-12.7%, 1.33%) rotate(-2.5deg); }
  100% { transform: translate(-12.7%, 1.33%) rotate(-2.5deg); }
}
.antariksa.foto .af-dewi > img { position: absolute; height: auto; max-width: none; }
.antariksa.foto .af-timbangan { animation: afAyun 12s ease-in-out infinite; will-change: transform; }
@keyframes afAyun { 0%, 33% { transform: rotate(0deg); } 40% { transform: rotate(6.5deg); } 46% { transform: rotate(-4.8deg); } 52% { transform: rotate(3.2deg); } 58% { transform: rotate(-1.9deg); } 64% { transform: rotate(.8deg); } 70%, 100% { transform: rotate(0deg); } }
.antariksa.foto .af-kilau-dewi { position: absolute; pointer-events: none; mix-blend-mode: screen;
  -webkit-mask-image: url(hero-dewi.webp); mask-image: url(hero-dewi.webp); -webkit-mask-size: 100% 100%; mask-size: 100% 100%;
  background: linear-gradient(112deg, transparent 0 40%, rgba(255, 240, 200, .6) 50%, transparent 60% 100%) no-repeat; background-size: 280% 100%; background-position: 130% 0; animation: afKilauD 12s ease-in-out infinite; }
@keyframes afKilauD { 0%, 38% { background-position: 130% 0; } 58%, 100% { background-position: -30% 0; } }
.af-jejak { stroke: #e3eeff; fill: none; }
.antariksa.foto.af-statis .af-dewi { display: none; }

/* penanda "memperbarui data" saat masuk seketika dari data tersimpan */
.memperbarui { position: fixed; top: calc(10px + env(safe-area-inset-top, 0px)); left: 50%; transform: translateX(-50%); z-index: 60; display: flex; align-items: center; gap: 8px; padding: 6px 14px; border-radius: 999px; background: var(--ink); color: var(--bg); font-size: 13px; font-weight: 600; box-shadow: 0 6px 20px rgba(0, 0, 0, .25); pointer-events: none; }
.memperbarui i { width: 12px; height: 12px; border-radius: 50%; border: 2px solid var(--bg); border-top-color: transparent; animation: putar 1s linear infinite; }

/* tombol musik & suara klik (seperti gim): di sebelah merek */
.merek .suara { margin-left: 6px; width: 34px; height: 34px; border-radius: 50%; border: 2px solid var(--ink); background: var(--surface); display: inline-grid; place-items: center; cursor: pointer; padding: 0; vertical-align: middle; transition: transform .15s ease, background-color .2s ease; }
.merek .suara:hover { transform: translateY(-1px); }
.merek .suara svg path { fill: none; stroke: var(--ink); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; }
.merek .suara svg .s-badan { fill: var(--ink); }
.merek .suara .s-silang { display: none; }
.merek .suara[aria-pressed="true"] { background: var(--pop); }
.merek .suara[aria-pressed="true"] svg path { stroke: #14132b; } .merek .suara[aria-pressed="true"] svg .s-badan { fill: #14132b; }
.merek .suara[aria-pressed="true"] .s-gel1 { animation: suaraGel 1.4s ease-in-out infinite; } .merek .suara[aria-pressed="true"] .s-gel2 { animation: suaraGel 1.4s ease-in-out infinite .35s; }
@keyframes suaraGel { 0%, 100% { opacity: .35; } 50% { opacity: 1; } }
.merek .suara[aria-pressed="false"] .s-gel1, .merek .suara[aria-pressed="false"] .s-gel2 { display: none; } .merek .suara[aria-pressed="false"] .s-silang { display: block; }
